    man_patches = image_patch.find("man")
    shirt_patches = image_patch.find("shirt")
    child_patches = image_patch.find("child")

    if not man_patches or not shirt_patches or not child_patches:
        return image_patch

    man_shirt_pairs = []
    for man in man_patches:
        for shirt in shirt_patches:
            if man.overlaps_with(shirt.left, shirt.lower, shirt.right, shirt.upper):
                man_shirt_pairs.append((man, shirt))

    if not man_shirt_pairs:
        return image_patch

    child_hand_pairs = []
    for man_shirt_pair in man_shirt_pairs:
        man, shirt = man_shirt_pair
        for child in child_patches:
            if child.overlaps_with(man.left, man.lower, man.right, man.upper):
                child_hand_pairs.append((man_shirt_pair, child))

    if not child_hand_pairs:
        return image_patch

    _, child = max(child_hand_pairs, key=lambda x: x[1].horizontal_center)
    return child

