def is_holding(child: ImagePatch, adult: ImagePatch) -> bool:
    child_center_x = (child.left + child.right) / 2
    child_center_y = (child.lower + child.upper) / 2
    adult_center_x = (adult.left + adult.right) / 2
    adult_center_y = (adult.lower + adult.upper) / 2

    return abs(child_center_x - adult_center_x) < 0.2 * (adult.right - adult.left) and \
           abs(child_center_y - adult_center_y) < 0.2 * (adult.upper - adult.lower)

